package org.json; import java.util.*; public class JSONObject { private final Map<String,Object> vals=new LinkedHashMap<>(); public JSONObject(){} public JSONObject(String s){} public JSONObject put(String k,Object v){vals.put(k,v);return this;} public String getString(String k){return String.valueOf(vals.get(k));} public int optInt(String k,int d){return d;} public long optLong(String k,long d){return d;} public String optString(String k){return optString(k,"");} public String optString(String k,String d){return String.valueOf(vals.getOrDefault(k,d));} public boolean optBoolean(String k,boolean d){return d;} public JSONObject getJSONObject(String k){return (JSONObject)vals.get(k);} public JSONObject optJSONObject(String k){return vals.get(k) instanceof JSONObject?(JSONObject)vals.get(k):null;} public JSONArray optJSONArray(String k){return vals.get(k) instanceof JSONArray?(JSONArray)vals.get(k):null;} public Object remove(String k){return vals.remove(k);} public Iterator<String> keys(){return vals.keySet().iterator();} public static String quote(String x){return "\""+x+"\"";} public String toString(){return vals.toString();} }